---@field Empty                         	UnityEngine.RectTransform               
local OverseaManageCafePackageNodeCell = Class('OverseaManageCafePackageNodeCell')
local FoodTypeCount = 3
local ReportDescPath = "Game.MaidCoffee.MaidCoffeeUIDialog.Cell.OSManegeReportDescriptionCell"
local MaidCoffeeUtils     = import("Game.MaidCoffee.MaidCoffeeUtils")
local CurryEnvPath = "Game.Behaviours.CommonCurrencyNode"
function OverseaManageCafePackageNodeCell:__init()
    self.reportDesEnv = nil
    self.currencyEnv = nil
end

function OverseaManageCafePackageNodeCell:__delete()
    self.reportDesEnv = nil
    self.currencyEnv = nil
end

function OverseaManageCafePackageNodeCell:Awake()
    self:InitNodeEnv()
end

function OverseaManageCafePackageNodeCell:InitNodeEnv()
    self.reportDesEnv = {}
    for i = 1, 3 do
        local node = self["ReportDescription"..i]
        if node then
            local env = CfUtils.GetLuaScr(node,ReportDescPath)
            if env then
                self.reportDesEnv[i] = env
            end
        end
    end

    if self.TextNumber then
        local env = CfUtils.GetLuaScr(self.TextNumber,CurryEnvPath)
        if env then
            self.currencyEnv = env
        end
    end
end

function OverseaManageCafePackageNodeCell:Start()
end

function OverseaManageCafePackageNodeCell:RefreshUI(i)
    self.tabIndex = i
    CfUtils.FillText(self.TextDesc,localize("套餐_num_",{_num_ = self.tabIndex}))
    ---判断当前套餐是否在售卖
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local menuInfo = component:GetCurIndexMenuInfo(self.tabIndex)
    local isSell = menuInfo:IsSell()
    local isHaveAdd = false
    local coinNum = 0
    local coinId
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local isCafeMax = component:IsToMaxCafeLevel()
    for i = 1, FoodTypeCount do
        local skillNode = self["ReportDescription"..i]
        if skillNode then
            if isSell then
                local saleRecipes = menuInfo.saleRecipes
                local packages = menuInfo.packages
                if saleRecipes[i] and saleRecipes[i].isDouble == 1 then
                    isHaveAdd = true
                    KTool.SetActive(skillNode,true)
                    self.reportDesEnv[i]:RefreshSkillDesShow(packages[i])
                else
                    KTool.SetActive(skillNode,false)
                end
            else
                KTool.SetActive(skillNode,false)
            end
        end
    end

    if isSell then
        local vo = MaidCoffeeUtils.GetMaidCoffeeMenuVo(i)
        for k, v in pairs(menuInfo.saleRecipes) do
            local addNum = isCafeMax and tonumber(vo.restaurantMaxRewardNum[k]) or tonumber(vo.restaurantExp[k])
            coinNum = coinNum + addNum
        end
        coinId = isCafeMax and tonumber(vo.restaurantMaxReward[1]) or tonumber(vo.restaurantExpId[1])
    end

    KTool.SetActive(self.Empty.gameObject,not isSell or not isHaveAdd)
    KTool.SetActive(self.TextNumber.gameObject,coinNum > 0)
    KTool.SetActive(self.TextMax.gameObject,isCafeMax)
    if coinNum > 0 then
        self.currencyEnv:SetCurrencyShow(coinId,coinNum)
    end

    if not isSell then
        CfUtils.FillText(self.EmptyDesc,localize("未设置套餐_num_",{_num_ = self.tabIndex}))
        CfUtils.SetUISwitchImage(self.ImgBg2,1)
        CfUtils.SetUISwitchText(self.TextDesc,1)

    else
        if  not isHaveAdd then
            CfUtils.FillText(self.EmptyDesc,localize("没有上架今日推荐的食谱"))
            CfUtils.SetUISwitchText(self.TextDesc,1)
            CfUtils.SetUISwitchImage(self.ImgBg2,1)
        else
            CfUtils.SetUISwitchText(self.TextDesc,2)
            CfUtils.SetUISwitchImage(self.ImgBg2,2)
        end
    end
    self:SetRecipeTypeIcon(menuInfo,isSell)

end

function OverseaManageCafePackageNodeCell:SetRecipeTypeIcon(data,isSelling)
    ---@type MaidCoffeeConstants
    local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")
    local packages = data.packages
    local saleRecipes = data.saleRecipes
    for i = 1, FoodTypeCount do
        if packages[i] then
            local type = packages[i].recipeType
            local icon = self["ImgIcon"..i]
            if icon then
                local iconPath = MaidCoffeeConstants.RecipeSkillTypeImg[type]
                if iconPath then
                    CfUtils.FillImage(icon,iconPath)
                end
                if isSelling and saleRecipes[i] and saleRecipes[i].recipeId == packages[i].recipeId then
                    CfUtils.SetUISwitchImage(icon,2)
                else
                    CfUtils.SetUISwitchImage(icon,1)
                end
            end
        end
    end
end

function OverseaManageCafePackageNodeCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return OverseaManageCafePackageNodeCell